def name_error_with_function_call(definition: str) -> bool:

    try:
        tree = ast.parse(definition)
    except SyntaxError as e:
        if "assignment to keyword argument" in str(e):
            return True
        else:
            return False

    for node in ast.walk(tree.body[0].value):

        function_name = None

        if isinstance(node, ast.FunctionDef): 
           function_name = node.name


        elif isinstance(node, ast.Assign): 

            try: target_id = node.targets[0].id
                except AttributeError as error:
                    continue


               assigned_value_exprs = [ast.unparse(assigned_val) for assigned_val in node.value.elts]



           if function_name is not None and all([f"{function_name}(" in expr for expr in assigned_value_exprs]):

                   return True

    return False


